// Generated by solid-platform. Cache the app shell and serve hashed assets
// cache-first, with a network-first navigation fallback for offline use.
const VERSION = 'solid-app-v1';
const SHELL = ['./', './index.html', './manifest.webmanifest', './icon.png'];

async function precache() {
  const cache = await caches.open(VERSION);
  await cache.addAll(SHELL);
  // Vite hashes bundle names, so read the shell HTML and cache the exact
  // scripts/styles it references. Without this an offline reload after the
  // first visit would miss the JS bundle.
  try {
    const response = await fetch('./index.html', { cache: 'reload' });
    const html = await response.text();
    const urls = [...html.matchAll(/(?:src|href)="(\.\/[^"]+)"/g)]
      .map((match) => match[1])
      .filter((url) => !url.startsWith('./http'))
      .filter((url) => !url.endsWith('.map'));
    await cache.addAll([...new Set(urls)]);
  } catch {
    // A network failure during install must not discard the shell cache.
  }
}

self.addEventListener('install', (event) => {
  event.waitUntil(precache().then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key !== VERSION)
            .map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    // New deployments win; the cached shell keeps the app usable offline.
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(VERSION).then((cache) => cache.put(request, copy));
          return response;
        })
        .catch(async () => {
          const cache = await caches.open(VERSION);
          return (
            (await cache.match(request)) ||
            (await cache.match('./index.html')) ||
            Response.error()
          );
        }),
    );
    return;
  }

  event.respondWith(
    caches.open(VERSION).then(async (cache) => {
      const cached = await cache.match(request);
      const network = fetch(request)
        .then((response) => {
          if (response.ok) cache.put(request, response.clone());
          return response;
        })
        .catch(() => undefined);
      return cached || (await network) || Response.error();
    }),
  );
});
